export const multiselect = <Options extends Option<Value>[], Value>(
  opts: MultiSelectOptions<Options, Value>
) => {

  return new MultiSelectPrompt({
    options: opts.options,
    initialValues: opts.initialValues,
    required: opts.required ?? true,
    cursorAt: opts.cursorAt,
    validate(selected: Value[]) {
      if (this.required && selected.length === 0) {
        return `Please select at least one option.\n${color.reset(
          color.dim(
            `Press ${color.gray(
              color.bgWhite(color.inverse(" space "))
            )} to select, ${color.gray(
              color.bgWhite(color.inverse(" enter "))
            )} to submit`
          )
        )}`;
      }
    },
    render() {
      const title = `${color.gray(S_BAR)}\n${symbol(this.state)} ${
        opts.message
      }\n`;

      switch (this.state) {
        case "submit": {
          return `${title}${color.gray(S_BAR)} ${
            this.options
              .filter(({ value }) => this.value.includes(value))
              .map((option) => opt(option, "submitted"))
              .join(color.dim(", ")) || color.dim("none")
          }`;
        }
        case "cancel": {
          const label = this.options
            .filter(({ value }) => this.value.includes(value))
            .map((option) => opt(option, "cancelled"))
            .join(color.dim(", "));
          return `${title}${color.gray(S_BAR)} ${
            label.trim() ? `${label}\n${color.gray(S_BAR)}` : ""
          }`;
        }
        case "error": {
          const footer = this.error
            .split("\n")
            .map((ln, i) =>
              i === 0
                ? `${color.yellow(S_BAR_END)} ${color.yellow(ln)}`
                : `   ${ln}`
            )
            .join("\n");
          return (
            title +
            color.yellow(S_BAR) +
            "  " +
            this.options
              .map((option, i) => {
                const selected = this.value.includes(option.value);
                const active = i === this.cursor;
                if (active && selected) {
                  return opt(option, "active-selected");
                }
                if (selected) {
                  return opt(option, "selected");
                }
                return opt(option, active ? "active" : "inactive");
              })
              .join(`\n${color.yellow(S_BAR)}  `) +
            "\n" +
            footer +
            "\n"
          );
        }
        default: {
          return `${title}${color.cyan(S_BAR)} ${this.options
            .map((option, i) => {
              const selected = this.value.includes(option.value);
              const active = i === this.cursor;
              if (active && selected) {
                return opt(option, "active-selected");
              }
              if (selected) {
                return opt(option, "selected");
              }
              return opt(option, active ? "active" : "inactive");
            })
            .join(`\n${color.cyan(S_BAR)}  `)}\n${color.cyan(S_BAR_END)}\n`;
        }
      }
    },
  }).prompt() as Promise<Value[] | symbol>;
};
